module.render:
    const esc = (s) => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

    // ---- vocabularies -------------------------------------------------
    // Short marker codes follow matplotlib. Line codes do too, except that
    // dotted is `..` rather than `:` — `:` already separates colour from label.
    const MARKS = { o:'circle', s:'square', '^':'triangle', v:'triangle-down', d:'diamond', D:'diamond', '*':'star' };
    const MARK_WORDS = ['circle','square','triangle','triangle-down','diamond','star','none'];
    const LINES = { '-':'solid', '--':'dashed', '..':'dotted', '-.':'dashdot' };
    const LINE_WORDS = ['solid','dashed','dotted','dashdot','none'];
    const DASH = { solid:'', dashed:'34 22', dotted:'1 20', dashdot:'34 18 1 18' };

    /** Parse one token into {mark?, line?}; returns null if it is not a token. */
    const parseToken = (raw) => {
      const t = String(raw).trim();
      if (!t) return null;
      const low = t.toLowerCase();
      if (MARK_WORDS.indexOf(low) >= 0) return { mark: low };
      if (LINE_WORDS.indexOf(low) >= 0) return { line: low };
      // glued or bare short form, e.g. "o--", "s", "-.", ".."
      const m = t.match(/^([osdD^v*])?(--|-\.|\.\.|-)?$/);
      if (!m || (!m[1] && !m[2])) return null;
      const out = {};
      if (m[1]) out.mark = MARKS[m[1]];
      if (m[2]) out.line = LINES[m[2]];
      return out;
    };

    /** Split "…colour… tok tok" into the colour and its tokens. Tokens are
     *  peeled off the END so colours that contain spaces — rgb(255, 0, 0) —
     *  survive untouched. */
    const splitHead = (head) => {
      const parts = String(head).trim().split(/\s+/);
      const toks = [];
      while (parts.length > 1) {
        const t = parseToken(parts[parts.length - 1]);
        if (!t) break;
        toks.unshift(t); parts.pop();
      }
      return { color: parts.join(' '), toks };
    };

    // ---- SVG handles --------------------------------------------------
    const starPoints = (cx, cy, r) => {
      const p = [];
      for (let k = 0; k < 10; k++) {
        const a = (-90 + k * 36) * Math.PI / 180;
        const rr = k % 2 === 0 ? r : r * 0.44;
        p.push((cx + rr * Math.cos(a)).toFixed(1) + ',' + (cy + rr * Math.sin(a)).toFixed(1));
      }
      return p.join(' ');
    };

    const markSvg = (mark, cx, cy, r, c) => {
      const f = ` fill="${c}"`;
      switch (mark) {
        case 'circle':   return `<circle cx="${cx}" cy="${cy}" r="${r}"${f}/>`;
        case 'square':   return `<rect x="${cx - r}" y="${cy - r}" width="${2 * r}" height="${2 * r}" rx="${(r * 0.18).toFixed(1)}"${f}/>`;
        case 'triangle': return `<polygon points="${cx},${cy - r} ${cx + r * 0.93},${cy + r * 0.72} ${cx - r * 0.93},${cy + r * 0.72}"${f}/>`;
        case 'triangle-down': return `<polygon points="${cx},${cy + r} ${cx + r * 0.93},${cy - r * 0.72} ${cx - r * 0.93},${cy - r * 0.72}"${f}/>`;
        case 'diamond':  return `<polygon points="${cx},${cy - r} ${cx + r * 0.84},${cy} ${cx},${cy + r} ${cx - r * 0.84},${cy}"${f}/>`;
        case 'star':     return `<polygon points="${starPoints(cx, cy, r * 1.12)}"${f}/>`;
        default:         return '';
      }
    };

    /** One handle, drawn in a 100-tall viewBox (240 wide when a line shows). */
    const handleSvg = (color, mark, line, px) => {
      const hasLine = line && line !== 'none';
      const w = hasLine ? 240 : 100;
      const c = esc(color);
      let body = '';
      if (hasLine) {
        const da = DASH[line] || '';
        body += `<line x1="4" y1="50" x2="236" y2="50" stroke="${c}" stroke-width="13" stroke-linecap="round"`
             + (da ? ` stroke-dasharray="${da}"` : '') + `/>`;
      }
      body += markSvg(mark, w / 2, 50, hasLine ? 32 : 42, c);
      const cls = `mdp-lg-swatch mdp-lg-${mark || 'none'}${hasLine ? ' mdp-lg-wide mdp-lg-line-' + line : ''}`;
      // width/height attributes give the element an intrinsic size; the CSS
      // above overrides them so the handle still scales with --mdp-px.
      const aw = (px * w / 100).toFixed(1);
      return `<svg class="${cls}" width="${aw}" height="${px}" viewBox="0 0 ${w} 100" preserveAspectRatio="xMidYMid meet" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">${body}</svg>`;
    };

    // ---- module arguments ---------------------------------------------
    const dir = (args.direction || 'row').toLowerCase() === 'column' ? 'column' : 'row';
    let defMark = String(args.shape || 'square').toLowerCase();
    let defLine = String(args.line || 'none').toLowerCase();
    if (defMark === 'line') { defMark = 'none'; if (defLine === 'none') defLine = 'solid'; }  // legacy shape: line
    if (MARK_WORDS.indexOf(defMark) < 0) defMark = 'square';
    if (LINE_WORDS.indexOf(defLine) < 0) defLine = 'none';
    const px = { small: 11, medium: 15, large: 20 }[String(args.size || 'medium').toLowerCase()] || 15;
    const size = `calc(${px} * var(--mdp-px, 1px))`;
    const gap = (args.gap && String(args.gap).trim()) || '8px 18px';
    const weight = String(args.bold) === 'true' ? '700' : '400';

    const items = [];
    sections.forEach((s) => {
      const m = String(s || '').trim().match(/^([\s\S]*?)[:|]\s*([\s\S]+)$/);
      if (!m) return;
      const head = splitHead(m[1]);
      let mark = defMark, line = defLine;
      if (head.toks.length) {
        // An entry that carries tokens describes its WHOLE handle: whatever it
        // does not name is off. So `-` is a bare line, `o` a bare marker and
        // `o-` both — the same reading as matplotlib's format strings.
        mark = 'none'; line = 'none';
        head.toks.forEach((t) => { if (t.mark) mark = t.mark; if (t.line) line = t.line; });
      }
      items.push({ color: head.color, label: m[2].trim(), mark, line });
    });

    // Labels are emitted as markdown blocks (blank-line padded, same trick as
    // the graph module's labels/caption), so Markdown + KaTeX typeset them.
    let html = `\n\n<div class="mdp-mod-legend mdp-lg-${dir}" style="--lg-size:${size}; --lg-weight:${weight}; gap:${gap};">`;
    items.forEach((it) => {
      html += `<div class="mdp-lg-item">${handleSvg(it.color, it.mark, it.line, px)}<div class="mdp-lg-label">\n\n${it.label}\n\n</div></div>`;
    });
    html += `</div>\n\n`;
    return html;

module.script:
export default {
  init(el) {
    const r = (typeof window !== 'undefined') && window.renderMathInElement;
    const t = el.textContent || '';
    if (!r || (t.indexOf('$') === -1 && t.indexOf('\\(') === -1)) return;
    try {
      r(el, {
        delimiters: [
          { left: '$$', right: '$$', display: false },
          { left: '$', right: '$', display: false },
          { left: '\\(', right: '\\)', display: false }
        ],
        throwOnError: false
      });
    } catch (e) { /* leave raw math visible on error */ }
  }
}
